package com.portfoliopro.controller; import com.portfoliopro.dto.TradeRequest; import com.portfoliopro.model.Trade; import com.portfoliopro.service.TradeService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class PortfolioController{private final TradeService t;public PortfolioController(TradeService t){this.t=t;}@GetMapping("/portfolio")public Map<String,Object> portfolio(Authentication a){return t.portfolio(a.getName());}@PostMapping("/trades")public Trade trade(Authentication a,@RequestBody TradeRequest r){return t.execute(a.getName(),r);}@GetMapping("/health")public Map<String,String> health(){return Map.of("status","UP");}}
